"use strict";(function(){const originalLoad=window.loadConfig,originalSave=window.saveConfig;window.loadConfig=function(){const config=originalLoad();config.rentals=(config.rentals||[]).filter(rental=>rental.id!=='uber');config.rentals.push({id:'uber',name:'Uber',type:'VAN',collection:'0001-01-01',return:'9999-12-31',system:true});return config};window.saveConfig=function(config){const clean={...config,rentals:(config.rentals||[]).filter(rental=>rental.id!=='uber')};originalSave(clean)};Editor.rentalEmoji=function(id){const list=(loadConfig().rentals||[]).filter(rental=>rental.id!=='uber'),index=list.findIndex(rental=>rental.id===id);return index>=0&&index<6?['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣'][index]:''};Editor.resetDay=function(day){const key=Editor.dateKey(day);if(!confirm('Reset this day to its default vehicle allocation and run order? Base jobs will return to unassigned.'))return;delete Editor.state().stops[key];delete Editor.state().orders[key];Object.entries(Editor.state().assignments).forEach(([assignmentKey,vehicle])=>{if(Editor.state().jobDates[assignmentKey]===key)delete Editor.state().assignments[assignmentKey]});Editor.refresh()};const apply=Editor.apply;Editor.apply=function(day){const result=apply(day);day.rentals=(day.rentals||[]).filter(rental=>rental.id!=='uber'||rental.rows.some(row=>row.editorStop||row.editorJob));[day.truck,day.van,...day.rentals].filter(Boolean).forEach(run=>run.rows.forEach(row=>{if(row.editorJob)row.transfers=row.transfers.replace(' | Dump ',' | Onsite Time: ')}));return result};window.renderConfig()})();
setTimeout(function(){
 const render=window.renderSchedule;
 function styleIcon(button,label){button.title=label;button.setAttribute('aria-label',label);button.classList.add('icon-btn');button.style.border='none';button.style.background='transparent';button.style.boxShadow='none';button.style.padding='2px 4px';}
 function decorate(schedule){document.querySelectorAll('#scheduleOutput .day').forEach((article,index)=>{const day=schedule[index];if(!day)return;const ids=Editor.ids(day);article.querySelectorAll('.warning.base .run-actions').forEach(actions=>{Array.from(actions.querySelectorAll('button')).forEach((button,i)=>{const id=ids[i];if(!id)return;button.textContent=id==='truck'?'🚚':id==='van'?'🚐':id==='uber'?'🚕':Editor.rentalEmoji(id)||'🚗';styleIcon(button,'Add to '+Editor.name(id));});});
 article.querySelectorAll('button').forEach(button=>{if(button.textContent.trim()==='Remove from Uber'){button.textContent='❌';styleIcon(button,'Remove from Uber — return stop to its original run');}});
 const primary=[['truck',day.truck],['van',day.van]].filter(([,run])=>run),special=(day.rentals||[]).filter(run=>run.rows&&run.rows.length).slice().sort((a,b)=>a.id==='uber'?-1:b.id==='uber'?1:0);const runs=primary.concat(special.map(run=>[run.id,run]));const tables=[...article.querySelectorAll('.vehicle-pair .schedule-table'),...article.querySelectorAll('.special-runs .schedule-table')];
 runs.forEach(([id,run],i)=>{const table=tables[i];if(!table)return;const shown=id==='truck'||id==='van'?run.rows:run.rows.filter(row=>row.editorStop||row.editorJob);shown.forEach((row,n)=>{if(!row.editorJob)return;const tr=table.tBodies[0]?.rows[n],job=(day.editorJobs||[]).find(candidate=>candidate.key===row.editorJob);if(!tr||!job)return;let actions=tr.querySelector('.run-actions');if(!actions){actions=document.createElement('div');actions.className='run-actions';tr.cells[1].append(actions);}let button=Array.from(actions.querySelectorAll('button')).find(b=>b.textContent.trim()==='❌');if(!button){button=document.createElement('button');actions.append(button);}button.type='button';button.textContent='❌';button.dataset.returnBase='true';styleIcon(button,'Return base job to unassigned bucket');button.onclick=()=>Editor.unassign(job);});});
 });}
 window.renderSchedule=function(schedule){const result=render(schedule);decorate(schedule);return result;};
 decorate(window.currentSchedule||[]);
},0);
